class Task:
    def __init__(self, period, execution_cost):
        self.T = period
        self.C = execution_cost
        self.U = self.C / self.T

def calculate_task_utilization(task):
    return task.C / task.T

def compute_total_utilization(task_system):
    U_total = 0
    for task_i in task_system:
        U_total += task_i.U
    return U_total

def get_job_deadline(task, release_time):
    # Assuming task.T is the period
    return release_time + task.T

def is_system_schedulable(task_system, scheduler):
    # This is a conceptual check, actual implementation depends on scheduler and simulation
    for task_i in task_system:
        for job in task_i.get_all_jobs():
            if job.completion_time > job.deadline:
                return False
    return True

def calculate_tardiness(completion_time, deadline):
    return max(0, completion_time - deadline)

def has_bounded_tardiness(task_system, scheduler, bound_B):
    # Conceptual check
    for task_i in task_system:
        for job in task_i.get_all_jobs():
            if calculate_tardiness(job.completion_time, job.deadline) > bound_B:
                return False
    return True

def is_schedulable_PD2_Pfair(task_system, M):
    U_total = compute_total_utilization(task_system)
    return U_total <= M

def has_bounded_tardiness_G_EDF(task_system, M):
    U_total = compute_total_utilization(task_system)
    return U_total <= M

def check_hard_realtime_schedulability(task_system, scheduler):
    # Check if all deadlines are met for all jobs
    return is_system_schedulable(task_system, scheduler)

def check_soft_realtime_schedulability(task_system, scheduler, bound_B):
    # Check if deadline tardiness is bounded by B for all jobs
    return has_bounded_tardiness(task_system, scheduler, bound_B)

def check_schedulability(task_system, scheduler_type, M, overheads):
    if scheduler_type == 'G-EDF':
        # Apply G-EDF test from literature
        return test_G_EDF(task_system, M, overheads)
    elif scheduler_type == 'P-EDF':
        # Apply first-fit decreasing heuristic
        return test_P_EDF(task_system, M, overheads)
    elif scheduler_type in ['PD2', 'S-PD2']:
        # Check total utilization against M
        U_total_with_overhead = compute_total_utilization_with_overheads(task_system, overheads)
        return U_total_with_overhead <= M
    else:
        return False

def check_soft_schedulability(task_system, scheduler_type, M, overheads):
    if scheduler_type in ['PD2', 'P-EDF']:
        # Use hard real-time tests (potentially with adjusted overheads/periods)
        return check_hard_schedulability(task_system, scheduler_type, M, overheads) # Conceptual call
    elif scheduler_type in ['G-EDF', 'NG-EDF']:
        # Simpler test for soft real-time
        U_total_with_overhead = compute_total_utilization_with_overheads(task_system, overheads)
        return U_total_with_overhead <= M
    else:
        return False
